import{_ as t,a as d,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"List GDPR Requests","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-gdpr-requests","title":"List Own GDPR Requests","description":"Retrieve a paginated list of the authenticated customer's own GDPR data requests, newest first.","query":"query GdprRequests(\\n  $sort: String\\n  $order: String\\n) {\\n  gdprRequests(\\n    first: 10\\n    after: null\\n    sort: $sort\\n    order: $order\\n  ) {\\n    edges {\\n      cursor\\n      node {\\n        _id\\n        type\\n        status\\n        message\\n        email\\n        revokedAt\\n        createdAt\\n        updatedAt\\n        customer {\\n          _id\\n        }\\n      }\\n    }\\n    pageInfo {\\n      startCursor\\n      endCursor\\n      hasNextPage\\n      hasPreviousPage\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"sort\\": \\"id\\",\\n  \\"order\\": \\"desc\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"gdprRequests\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MQ==\\",\\n          \\"node\\": {\\n            \\"_id\\": 12,\\n            \\"type\\": \\"delete\\",\\n            \\"status\\": \\"pending\\",\\n            \\"message\\": \\"Please delete my account data.\\",\\n            \\"email\\": \\"jane@example.com\\",\\n            \\"revokedAt\\": null,\\n            \\"createdAt\\": \\"2026-06-25T10:30:00+00:00\\",\\n            \\"updatedAt\\": \\"2026-06-25T10:30:00+00:00\\",\\n            \\"customer\\": {\\n              \\"_id\\": 7\\n            }\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"startCursor\\": \\"MQ==\\",\\n        \\"endCursor\\": \\"MQ==\\",\\n        \\"hasNextPage\\": false,\\n        \\"hasPreviousPage\\": false\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"GDPR disabled","cause":"GDPR data requests are turned off in the store's admin configuration","solution":"Re-enable GDPR from the admin configuration before calling this query"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/gdpr-requests/queries/list-gdpr-requests.md","filePath":"api/graphql-api/shop/gdpr-requests/queries/list-gdpr-requests.md","lastUpdated":1787290888000}`),s={name:"api/graphql-api/shop/gdpr-requests/queries/list-gdpr-requests.md"};function a(n,e,c,i,u,l){return o(),d("div",null,e[0]||(e[0]=[r('<h1 id="list-gdpr-requests" tabindex="-1">List GDPR Requests <a class="header-anchor" href="#list-gdpr-requests" aria-label="Permalink to &quot;List GDPR Requests&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>gdprRequests</code> query returns a paginated list of the authenticated customer&#39;s <strong>own</strong> GDPR data requests. Requests are always scoped to the logged-in customer — you can never see another customer&#39;s requests. Results are ordered newest first by default.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This query requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="gdpr-must-be-enabled" tabindex="-1">GDPR must be enabled <a class="header-anchor" href="#gdpr-must-be-enabled" aria-label="Permalink to &quot;GDPR must be enabled&quot;">​</a></h2><p>If GDPR data requests are disabled in the store&#39;s admin configuration, the query fails with the message <strong>&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</strong> in <code>errors[]</code>. The feature has been turned off on the admin side.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>first</code></td><td><code>Int</code></td><td>❌ No</td><td>Number of items to return (forward pagination). Default: <code>30</code></td></tr><tr><td><code>after</code></td><td><code>String</code></td><td>❌ No</td><td>Cursor for forward pagination. Use <code>endCursor</code> from a previous response.</td></tr><tr><td><code>last</code></td><td><code>Int</code></td><td>❌ No</td><td>Number of items for backward pagination. Default: <code>30</code></td></tr><tr><td><code>before</code></td><td><code>String</code></td><td>❌ No</td><td>Cursor for backward pagination. Use <code>startCursor</code> from a previous response.</td></tr><tr><td><code>sort</code></td><td><code>String</code></td><td>❌ No</td><td>Sort column: <code>id</code> or <code>created_at</code>. Default <code>id</code>.</td></tr><tr><td><code>order</code></td><td><code>String</code></td><td>❌ No</td><td>Sort direction: <code>asc</code> or <code>desc</code>. Default <code>desc</code>.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>edges</code></td><td><code>[GdprRequestEdge]</code></td><td>Array of request edges with cursor and node.</td></tr><tr><td><code>edges.cursor</code></td><td><code>String!</code></td><td>Cursor for this edge, used in pagination.</td></tr><tr><td><code>edges.node</code></td><td><code>GdprRequest</code></td><td>The GDPR request object.</td></tr><tr><td><code>edges.node._id</code></td><td><code>Int!</code></td><td>Numeric request ID.</td></tr><tr><td><code>edges.node.type</code></td><td><code>String!</code></td><td>Request type: <code>delete</code> or <code>update</code>.</td></tr><tr><td><code>edges.node.status</code></td><td><code>String!</code></td><td>Request status: <code>pending</code>, <code>processing</code>, <code>declined</code>, <code>approved</code>, <code>revoked</code>.</td></tr><tr><td><code>edges.node.message</code></td><td><code>String!</code></td><td>The customer&#39;s message describing the request.</td></tr><tr><td><code>edges.node.email</code></td><td><code>String!</code></td><td>Email address tied to the request.</td></tr><tr><td><code>edges.node.revokedAt</code></td><td><code>String</code></td><td>Timestamp when the request was revoked, or <code>null</code>.</td></tr><tr><td><code>edges.node.createdAt</code></td><td><code>String</code></td><td>Request creation timestamp.</td></tr><tr><td><code>edges.node.updatedAt</code></td><td><code>String</code></td><td>Request last update timestamp.</td></tr><tr><td><code>edges.node.successMessage</code></td><td><code>String</code></td><td>Confirmation text. Populated only on create, revoke, and delete results — <code>null</code> when listing.</td></tr><tr><td><code>edges.node.customer</code></td><td><code>Customer</code></td><td>The customer who owns the request.</td></tr><tr><td><code>edges.node.customer._id</code></td><td><code>Int!</code></td><td>Numeric customer ID of the owner.</td></tr><tr><td><code>pageInfo</code></td><td><code>GdprRequestPageInfo!</code></td><td>Pagination metadata.</td></tr><tr><td><code>pageInfo.startCursor</code></td><td><code>String</code></td><td>Cursor for the first item in the page.</td></tr><tr><td><code>pageInfo.endCursor</code></td><td><code>String</code></td><td>Cursor for the last item in the page.</td></tr><tr><td><code>pageInfo.hasNextPage</code></td><td><code>Boolean!</code></td><td>Whether more pages exist forward.</td></tr><tr><td><code>pageInfo.hasPreviousPage</code></td><td><code>Boolean!</code></td><td>Whether more pages exist backward.</td></tr><tr><td><code>totalCount</code></td><td><code>Int!</code></td><td>Total number of the customer&#39;s requests.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/gdpr-requests/queries/view-gdpr-request.html">View GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/mutations/create-gdpr-request.html">Raise a GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/">GDPR Requests Overview</a></li></ul>',13)]))}const g=t(s,[["render",a]]);export{p as __pageData,g as default};
